#include "thinkercad/measurements.hpp"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace thinkercad {
Measurements measure(const std::vector<TimedValue>& samples){Measurements result;bool first=true;double area=0,duration=0,high=0;std::vector<double> rising;
for(const auto& s:samples)if(s.value){if(first){result.minimum=result.maximum=*s.value;first=false;}else{result.minimum=std::min(result.minimum,*s.value);result.maximum=std::max(result.maximum,*s.value);}}
if(first)return result;double threshold=(result.minimum+result.maximum)/2;for(std::size_t i=1;i<samples.size();++i){auto a=samples[i-1],b=samples[i];if(!a.value||!b.value||b.seconds<=a.seconds)continue;double dt=b.seconds-a.seconds;area+=dt*(*a.value**a.value);duration+=dt;if(*a.value>=threshold)high+=dt;if(result.maximum-result.minimum>1e-9&&*a.value<threshold&&*b.value>=threshold)rising.push_back(b.seconds);}
result.rms=duration?std::sqrt(area/duration):0;if(duration&&result.maximum-result.minimum>1e-9)result.duty=high/duration;if(rising.size()>=2)result.frequency=(rising.size()-1)/(rising.back()-rising.front());return result;}
namespace {std::optional<double> at(const std::vector<TimedValue>& s,double t){auto it=std::upper_bound(s.begin(),s.end(),t,[](double value,const TimedValue& p){return value<p.seconds;});if(it==s.begin()||s.empty()||t>s.back().seconds)return {};return (--it)->value;}}
std::vector<DecodedByte> decodeUart(const std::vector<TimedValue>& samples,unsigned baud){if(!baud||baud>2000000)throw std::invalid_argument("Invalid UART baud");std::vector<DecodedByte> result;double next=0,bit=1.0/baud;for(std::size_t i=1;i<samples.size();++i){auto a=samples[i-1],b=samples[i];if(!a.value||!b.value||a.value!=1||b.value!=0||b.seconds<next)continue;double start=b.seconds;auto center=at(samples,start+.5*bit);if(!center||*center!=0)continue;DecodedByte byte{start,0,true,{}};for(int j=0;j<8;++j){auto value=at(samples,start+(1.5+j)*bit);if(!value){byte.valid=false;break;}if(*value>=.5)byte.value|=1u<<j;}auto stop=at(samples,start+9.5*bit);if(!stop||*stop<.5){byte.valid=false;byte.detail="framing/incomplete";}result.push_back(byte);next=start+10*bit;}return result;}
std::vector<DecodedByte> decodeSpi(const std::vector<TimedValue>& clock,const std::vector<TimedValue>& data,bool rising,bool msbFirst){std::vector<DecodedByte> result;unsigned value=0,count=0;double start=0;for(std::size_t i=1;i<clock.size();++i){if(!clock[i-1].value||!clock[i].value||*clock[i-1].value==*clock[i].value||(*clock[i].value>=.5)!=rising)continue;auto bit=at(data,clock[i].seconds);if(!bit){value=count=0;continue;}if(!count)start=clock[i].seconds;unsigned b=*bit>=.5;if(msbFirst)value=(value<<1)|b;else value|=b<<count;if(++count==8){result.push_back({start,value,true,{}});value=count=0;}}return result;}
std::vector<DecodedByte> decodeI2c(const std::vector<TimedValue>& clock,const std::vector<TimedValue>& data){std::vector<DecodedByte> result;bool active=false,address=true;unsigned value=0,count=0;double start=0;std::size_t d=1;
for(std::size_t i=1;i<clock.size();++i){while(d<data.size()&&data[d].seconds<=clock[i].seconds){auto a=data[d-1],b=data[d];auto scl=at(clock,b.seconds);if(scl&&*scl>=.5&&a.value&&b.value&&*a.value!=*b.value){active=*b.value<.5;if(active){address=true;count=value=0;}}++d;}if(!active||!clock[i-1].value||!clock[i].value||*clock[i-1].value>=.5||*clock[i].value<.5)continue;auto bit=at(data,clock[i].seconds);if(!bit){active=false;continue;}if(!count)start=clock[i].seconds;if(count<8)value=(value<<1)|(*bit>=.5);if(++count==9){result.push_back({start,value,*bit<.5,address?"address+R/W":"data"});address=false;value=count=0;}}
return result;}
}
